mapper.sql:
SELECT ESS.APPLY_NO, ESS.PERSON_ID, ESS.APPLY_DATE_TIME, ESS.APPLY_TIME, ESS.OT_TYPE_CODE, ESS.OT_TYPE_CODE_NAME, ESS.OT_APPLY_HOUR, ESS.APPLY_OT_DATE, ESS.FROM_DATE, ESS.TO_DATE, ESS.OT_FROM_TIME, ESS.OT_TO_TIME, ESS.ACTIVITY, ESS.CONFIRM_FLAG, ESS.APPLY_OT_REMARK, ESS.LOCAL_NAME, ESS.EMPID, ESS.DEPTNO, ESS.EMP_OFFICE, ESS.OT_OVER, ESS.DEPT_NAME, ESS.POST_GRADE_NO, ESS.POST_GRADE_NAME, ESS.POST_FAMILY, ESS.POST_FAMILY_NAME, ESS.CONFIRM_BY, ESS.OT_TOTAIL FROM (SELECT OT.APPLY_NO, OT.PERSON_ID, OT.APPLY_TIME APPLY_DATE_TIME, TO_CHAR(OT.APPLY_TIME, 'DD/MM/YYYY') APPLY_TIME, OT.OT_TYPE_CODE, get_global_name(OT.OT_TYPE_CODE, #{lang, jdbcType=VARCHAR}) OT_TYPE_CODE_NAME, OT.OT_APPLY_HOUR, OT.APPLY_OT_DATE APPLY_OT_DATE_RAW, TO_CHAR(OT.APPLY_OT_DATE, 'DD/MM/YYYY') APPLY_OT_DATE, TO_CHAR(OT.OT_FROM_TIME, 'DD/MM/YYYY HH24:MI') FROM_DATE, TO_CHAR(OT.OT_TO_TIME, 'DD/MM/YYYY HH24:MI') TO_DATE, TO_CHAR(OT.OT_FROM_TIME, 'HH24:MI') OT_FROM_TIME, TO_CHAR(OT.OT_TO_TIME, 'HH24:MI') OT_TO_TIME, OT.ACTIVITY, OT.CONFIRM_FLAG, OT.APPLY_OT_REMARK, HR.LOCAL_NAME, HR.EMPID, HR.DEPTNO, HR.EMP_OFFICE, '0' OT_OVER, get_dept_name(HR.DEPTNO, #{lang, jdbcType=VARCHAR}) DEPT_NAME, HR.POST_GRADE_NO, get_global_name(HR.POST_GRADE_NO, #{lang, jdbcType=VARCHAR}) POST_GRADE_NAME, HR.POST_FAMILY, get_global_name(HR.POST_FAMILY, #{lang, jdbcType=VARCHAR}) POST_FAMILY_NAME, GET_UPDATED_INFO(OT.CONFIRM_BY) CONFIRM_BY, GET_AR_OT_TOTAIL(TO_CHAR(OT.APPLY_OT_DATE, 'YYYY/MM/DD'), #{cpnyId, jdbcType=VARCHAR}, OT.PERSON_ID, '30') OT_TOTAIL FROM ESS_APPLY_OT OT, HR_EMPLOYEE HR WHERE OT.PERSON_ID = HR.PERSON_ID AND OT.AFFIRM_FLAG = 14014308 AND OT.ACTIVITY = '1' AND OT.PERSON_ID NOT LIKE '111111%' AND OT.CPNY_ID = #{cpnyId, jdbcType=VARCHAR} UNION ALL SELECT OTO.APPLY_NO, OTO.PERSON_ID, OTO.APPLY_TIME APPLY_DATE_TIME, TO_CHAR(OTO.APPLY_TIME, 'DD/MM/YYYY') APPLY_TIME, OTO.OT_TYPE_CODE, '(OT Over) ' || get_global_name(OTO.OT_TYPE_CODE, #{lang, jdbcType=VARCHAR}) OT_TYPE_CODE_NAME, OTO.OT_APPLY_HOUR, OTO.APPLY_OT_DATE APPLY_OT_DATE_RAW, TO_CHAR(OTO.APPLY_OT_DATE, 'DD/MM/YYYY') APPLY_OT_DATE, TO_CHAR(OTO.OT_FROM_TIME, 'DD/MM/YYYY HH24:MI') FROM_DATE, TO_CHAR(OTO.OT_TO_TIME, 'DD/MM/YYYY HH24:MI') TO_DATE, TO_CHAR(OTO.OT_FROM_TIME, 'HH24:MI') OT_FROM_TIME, TO_CHAR(OTO.OT_TO_TIME, 'HH24:MI') OT_TO_TIME, OTO.ACTIVITY, OTO.CONFIRM_FLAG, OTO.APPLY_OT_REMARK, HR.LOCAL_NAME, HR.EMPID, HR.DEPTNO, HR.EMP_OFFICE, '1' OT_OVER, get_dept_name(HR.DEPTNO, #{lang, jdbcType=VARCHAR}) DEPT_NAME, HR.POST_GRADE_NO, get_global_name(HR.POST_GRADE_NO, #{lang, jdbcType=VARCHAR}) POST_GRADE_NAME, HR.POST_FAMILY, get_global_name(HR.POST_FAMILY, #{lang, jdbcType=VARCHAR}) POST_FAMILY_NAME, GET_UPDATED_INFO(OTO.CONFIRM_BY) CONFIRM_BY, GET_AR_OT_TOTAIL(TO_CHAR(OTO.APPLY_OT_DATE, 'YYYY/MM/DD'), #{cpnyId, jdbcType=VARCHAR}, OTO.PERSON_ID, '301') OT_TOTAIL FROM ESS_APPLY_OT_OVER OTO, HR_EMPLOYEE HR WHERE OTO.PERSON_ID = HR.PERSON_ID AND OTO.AFFIRM_FLAG = 14014308 AND OTO.ACTIVITY = '1' AND OTO.PERSON_ID NOT LIKE '111111%' AND OTO.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}) ESS WHERE 1 = 1
AND ESS.CONFIRM_FLAG = #{searchConfirmFlag, jdbcType=VARCHAR}
AND ESS.CONFIRM_FLAG = '0'
AND (UPPER(ESS.EMPID) LIKE '%' || UPPER(#{searchEmpId, jdbcType=VARCHAR}) || '%' OR CONVERTTOUNSIGN(UPPER(ESS.LOCAL_NAME)) LIKE '%' || CONVERTTOUNSIGN(UPPER(#{searchEmpId, jdbcType=VARCHAR})) || '%')
AND ESS.DEPTNO IN
#{deptNo, jdbcType=VARCHAR}
AND ESS.OT_TYPE_CODE = #{searchOtTypeCode, jdbcType=VARCHAR}
AND ESS.OT_OVER = #{searchOtOver, jdbcType=VARCHAR}
AND ESS.APPLY_OT_DATE_RAW >= TO_DATE(#{fromDate, jdbcType=VARCHAR}, 'YYYY-MM-DD')
AND ESS.APPLY_OT_DATE_RAW < TO_DATE(#{toDate, jdbcType=VARCHAR}, 'YYYY-MM-DD') + 1

mapper.select:
SELECT * FROM (
    SELECT INNER_Q.*, ROWNUM AS RN FROM (

        ORDER BY ESS.APPLY_DATE_TIME DESC
    ) INNER_Q
    WHERE ROWNUM <= #{start, jdbcType=INTEGER} + #{length, jdbcType=INTEGER}
) WHERE RN > #{start, jdbcType=INTEGER}

